begin;
create function pg_temp.model_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
do $$declare req uuid:=gen_random_uuid();u uuid:=gen_random_uuid();j jsonb;g jsonb;scope jsonb;b jsonb;begin
 perform pg_temp.model_assert(not public.slm_model_ready(),'candidate disabled by migration');
 perform public.slm_model_prepare();
 perform pg_temp.model_assert(public.slm_model_ready(),'empty test model explicitly prepared');
 j:=public.slm_model_signup_begin(req,repeat('0',64),'ModelNick','','');
 begin perform public.slm_model_signup_begin(gen_random_uuid(),repeat('1',64),'modelnick','','');raise exception 'duplicate_accepted';exception when unique_violation then null;end;
 perform pg_temp.model_assert(not exists(select 1 from public.slm_profiles),'reservation never creates partially active account');
 insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data) values(u,j->>'auth_email',now(),jsonb_build_object('slm_signup_request',req));
 perform pg_temp.model_assert(public.slm_model_signup_finish(req,repeat('0',64))=u,'signup binds same Auth UUID');
 perform pg_temp.model_assert(public.slm_model_signup_finish(req,repeat('0',64))=u,'signup finish idempotent');
 insert into auth.sessions(id,user_id) values(u,u);perform public.slm_account_accept_session(u,u,1);
 perform pg_temp.model_assert((public.slm_model_resolve('modelnick')->>'user_id')::uuid=u,'nickname resolver normalized');
 perform pg_temp.model_assert(public.slm_model_resolve(j->>'auth_email') is null,'internal Auth email is not public login');
 perform pg_temp.model_assert(public.slm_model_resolve('000000999') is null,'phone resolver has no fallback');
 perform pg_temp.model_assert((select role='member' from public.slm_roles where user_id=u) and not exists(select 1 from public.slm_group_members where user_id=u),'signup grants no groups/global admin');
 g:=public.slm_groups_dispatch(u,u,'create',jsonb_build_object('name','Own fixture group','request_id',gen_random_uuid()));
 scope:=jsonb_build_array(g->>'group_id');
 b:=jsonb_build_object('nickname','ChangedNick','expected_nickname','ModelNick','first_name','Given','full_name','Given Surname','display_as','full_name','jersey_number',27,'contact_phone','','group_scope',scope,'accept_disclosure',false,'request_id',gen_random_uuid());
 begin perform public.slm_model_profile_save(u,u,b);raise exception 'disclosure_accepted';exception when others then if sqlerrm<>'consent_required' then raise;end if;end;
 perform pg_temp.model_assert((select nickname='ModelNick' from public.slm_player_profiles where user_id=u) and (select nickname_key='modelnick' from public.slm_identity_registry where user_id=u),'consent denial rolls back canonical rename');
 perform public.slm_model_profile_save(u,u,b||jsonb_build_object('accept_disclosure',true));
 perform pg_temp.model_assert((select nickname='ChangedNick' and jersey_number=27 from public.slm_player_profiles where user_id=u) and (select display_as='full_name' from public.slm_profiles where user_id=u),'profile and nickname atomic');
 perform pg_temp.model_assert((select share_full_name from public.slm_group_members where user_id=u and group_id=(g->>'group_id')::uuid),'PR16 disclosure preserved');
 perform pg_temp.model_assert(public.slm_model_resolve('ModelNick') is null and (public.slm_model_resolve('ChangedNick')->>'user_id')::uuid=u,'old nickname retired immediately');
 perform pg_temp.model_assert(slm_private.session_valid(u,u,false) and (select operation_id is null from public.slm_account_security where user_id=u),'combined write preserves current session without pending');
 begin perform public.slm_model_profile_save(u,u,b||jsonb_build_object('current_password','NeverStore'));raise exception 'secret_accepted';exception when others then if sqlerrm<>'invalid_input' then raise;end if;end;
 perform pg_temp.model_assert(not exists(select 1 from public.slm_v2_requests where body::text like '%NeverStore%'),'SQL rejects secret-bearing payload');
 perform pg_temp.model_assert(not has_function_privilege('authenticated','public.slm_model_signup_finish(uuid,text)','execute') and not has_table_privilege('authenticated','public.slm_signup_jobs','select'),'signup capabilities private and RPC denied');
 perform public.slm_model_signup_begin(gen_random_uuid(),repeat('1',64),'ModelNick','','');
 perform pg_temp.model_assert((select count(*)=2 from public.slm_signup_jobs where nickname_key='modelnick'),'completed registration history does not reserve retired nickname');
 update auth.users set email_confirmed_at=null where id=u;
 perform pg_temp.model_assert(public.slm_model_resolve('ChangedNick') is null,'resolver fails closed when Auth becomes unconfirmed');
end$$;
rollback;
